import{a as e}from"./chunk-2RJSKV3I.js";import{a as o}from"./chunk-23QORGSQ.js";import"./chunk-U37H3HIF.js";var i=e(o,["선택 사항이에요. 화면에 보이는 이름, 도우미용으로 만드는 파일 이름, 사이드바의 링크에만 쓰여요. 도우미와 연결되는 것은 없어요.","브라우저가 열리지 않게 막았어요. 이 페이지의 팝업을 허용한 뒤 다시 시도해 주세요.","내 어시스턴트","링크는 https:// 로 시작해요","이름","내 도우미","없음, 또는 지정 안 함","지정된 도우미가 없어요.","이제 도우미는 {name}이에요.","지금 {name} 열기","이름을 클릭하면 여는 곳","다른 도우미…","바꿔 가며 쓰는 다른 어시스턴트","사이드바에서 어시스턴트 이름을 클릭해도 이 목록이 나옵니다. 거기서 하나를 고르면 자기 링크로 열리고 사용 중인 어시스턴트가 됩니다.","오른쪽 창에서","나란히 쓰기: 모든 화면의 사이드바에 있어요. Chrome에서는 거기서 마우스 오른쪽 버튼을 누르고 ‘분할 보기에서 링크 열기’를 고르면 한 창에서 둘 다 볼 수 있어요. Grading Studio는 도우미에게 아무것도 보내지 않아요. 도우미는 선생님이 붙여 넣거나 첨부한 것만 볼 수 있어요.","도우미 바꾸기","도우미 링크 바꾸기","전환할 도우미 바꾸기","도우미가 열리는 곳 바꾸기","새 탭","여는 주소","비워 두면 기본 페이지가 열려요. 직접 링크를 넣으면 학교 계정, 프로젝트, 직접 저장한 도우미로 바로 갈 수 있어요.","내 AI 도우미","돌려주는 파일의 기본 설정이에요. 과제마다 ‘돌려주기’ 상자에서 바꿀 수 있어요.","기준 답안지의 이름 가리기","돌려주기","파일마다 학생과 과제 이름 붙이기","학생마다 PDF 하나","83%","83.3%","83.33%","‘성적’ 탭과 성적부에서 학급 평균이나 학기 성적을 어떻게 표시할지예요. 계산할 때는 반올림하지 않아요.","평균의 소수 자릿수","브라우저의 막대를 숨겨요. 글 입력란이 아니면 어디서든 F를 눌러도 되고, Esc로 나가요.","전체 화면","전체 화면","전체 화면 끝내기","나만의 목록: 기능, 성취 기준 등 점수를 따로 보고 싶은 것은 무엇이든요.","새 목표 (선생님의 말로)","추가","{name}을(를) 뺐어요.","학습 목표","목표 {n}","선택 사항이에요. 목표는 점수를 따로 보고 싶은 무엇이든 될 수 있어요. ‘근거를 활용한다’ 같은 기능이나 학교의 성취 기준 등이요. 루브릭 항목과 퀴즈 문항에 목표를 붙이면 학급마다 ‘학습 목표’ 탭이 생겨요.","빼기","학습 목표 추가","학습 목표 옮기기","학습 목표 이름 바꾸기","학습 목표 빼기","루브릭 항목은 ‘루브릭 설정’에서, 퀴즈 문항은 ‘퀴즈 상자’에서 목표를 붙여요. 목표를 빼면 붙어 있던 곳에서도 빠지고, 점수는 바뀌지 않아요.","이미 목록에 있는 목표예요.","위로 이동","내 설정","이 컴퓨터에 있는 전용 폴더로, {name}이(가) 여기서 수업, 단원, 활동, 루브릭, 시간표를 읽고 바꿀 수 있어요. 여기에 저장된 초안은 과목 흐름에 ‘검토 안 함’으로 표시되어 들어와요. 채점 자료는 절대 들어가지 않아요.","수업 계획 폴더에서 들어왔어요. 아직 검토하지 않았어요.","이 브라우저에서 다시 권한이 필요해요:","내 버전으로 돌아가기","내 버전으로 돌아갔어요. {name}의 버전은 ‘버전’에 있어요.","수업 계획 폴더에서 새 항목 {a}개, 업데이트 {c}개","수업 계획 폴더에서 업데이트 {n}개","수업 계획 폴더에서 새 항목 {n}개","폴더 변경","{name}이(가) 수업 계획 폴더에서 바꿨어요. 아직 검토하지 않았어요. 선생님 버전은 ‘버전’에 있어요.","그 폴더를 쓸 수 없었어요","그 폴더에는 Grading Studio 채점 파일이 있어요. ‘수업’처럼 수업 계획만을 위한 폴더를 고르거나 만들어 주세요.","수업 계획 폴더","수업 계획 폴더 연결","수업 계획 폴더 연결됨: {name}","연결됨:","수업 계획 폴더 확인","이 브라우저는 폴더를 연결할 수 없어요. 컴퓨터의 Chrome이나 Edge에서는 돼요.","연결된 폴더가 없어요.","수업 계획 폴더에 바뀐 것이 없어요","다시 권한 주기","수업 계획 폴더를 읽지 못했어요","한번 읽어 본 뒤 검토함으로 표시하세요.","검토함으로 표시","샘플이라서 여기서는 폴더 연결이 꺼져 있어요. 샘플에서 나가면 선생님의 수업에 쓸 수 있어요.","{name}의 버전 (내 버전으로 돌아갔어요)","수업 계획 폴더에 권한이 필요합니다","수업 계획 폴더가 연결되지 않았습니다","Grading Studio QR 코드","휴대폰 카메라를 코드에 비추고 링크를 탭하거나 위 주소를 입력하세요.","iPhone: Safari에서 공유를 탭한 다음 홈 화면에 추가를 탭하세요.","Android: Chrome에서 ⋮ 메뉴를 누른 뒤 ‘홈 화면에 추가’ 또는 ‘앱 설치’를 누르세요.","홈 화면에서 Grading Studio를 열고 Google로 로그인을 탭하세요. 이 컴퓨터와 같은 Google 계정을 사용하세요.","이제 학급, 점수, 할 일이 양쪽에서 같게 유지됩니다. 휴대폰에서는 점수를 입력하고 과제를 볼 수 있으며, 채점은 컴퓨터에서 합니다.","Google에서 앱이 확인되지 않았다고 표시되면 고급을 탭한 다음 Grading Studio(으)로 이동을 탭하세요. 로그인 키는 Google의 검토가 아니라 사용 중인 사본을 위해 만들어졌으며, 앱은 Drive에 있는 자체 숨김 폴더만 사용할 수 있습니다.","휴대폰에서 사용","휴대폰에서는 버튼이 더 크고 탭이 아래쪽에 있어요. 답안지는 컴퓨터에 남고, 점수, 출석, 수업 계획, 할 일은 여기서 쓸 수 있어요.","휴대폰 화면 배치","다음에 휴대폰에서 페이지를 열 때 적용돼요","휴대폰에서는 휴대폰 화면 배치 사용","휴대폰 버전 열기","여기서 보려면 이 앱을 좁은 창으로 열어 보세요. 내용은 똑같아요.","예: IB MYP. MYP 선생님이 새 학급을 만들면 MYP 평가 기준이 미리 들어가요. 해당하지 않으면 비워 두세요.","교육 과정: {name}.","교육 과정","가르치는 교육 과정","지정된 교육 과정이 없어요.","교육 과정 바꾸기","로그인할 때까지 여기 작업은 동기화를 기다려요.","다시 로그인","Google에서 다시 로그인하라고 해요","컴퓨터와 같은 Google 계정으로 로그인하세요. 반, 점수, 수업 계획, 할 일이 여기로 옵니다.","Google로 로그인","컴퓨터의 작업 가져오기","선생님이 직접 파일을 주지 않는 한 AI 도우미에게는 아무것도 가지 않아요. 답안지, 이름, 점수, 의견은 이 브라우저와 선생님이 연결한 폴더에만 남아요.","과제의 ‘설정’에 있는 ‘도우미와 공유’는 도우미에게 줄 파일을 만들어요. 이름을 가린 답안지나 채점 표시만 담겨요. 학생은 각각 무작위 코드로 바뀌고, 코드 대조표는 이 브라우저에만 남아요.","수업 계획 폴더에는 수업만 들어가요. 도우미가 컴퓨터의 폴더에서 작업하게 하려면 이 폴더로 정해 주세요. 채점 자료는 절대 들어가지 않고, 채점 파일이 있는 폴더는 수업 계획에서 받지 않아요.","‘학급’ 아래 ‘내 설정’에서 도우미에게 설정을 대신 써 달라는 프롬프트를 줄 수 있어요. 학생에 관한 내용은 절대 들어가지 않아요.","도우미가 볼 수 있는 것과 없는 것","도움말의 ‘개인정보 보호’","이 컴퓨터에서 앱 글자를 크게 또는 작게 해요. 채점 중인 답안지는 자체 확대 비율을 그대로 유지해요.","앱 글자 크기","크게","보통","작게","아주 크게","선생님이 일하는 방식을 하나의 글로 정리한 거예요. 학급과 수업 시간, 달력, 학기, 평가 방식, 저장한 루브릭과 의견이 들어가요. 학생에 관한 내용은 절대 들어가지 않아요. 도우미나 동료에게서 가져오거나, 다른 컴퓨터에서 쓰도록 내 설정을 복사할 수 있어요.","2번 슬라이드에 수업 순서 넣기","AI 도우미는 {name}","지정된 AI 도우미 없음","사이드바 도우미 목록에 없는 것: {list}","앱이 아는 어시스턴트가 모두 사이드바 목록에 있습니다","도우미는 화면 오른쪽 창에서 열려요","도우미는 새 탭에서 열려요","도우미는 {link}에서 열려요","도우미는 기본 페이지에서 열려요","직접 링크를 넣은 다른 도우미: {list}","내 링크가 있는 다른 어시스턴트가 없습니다","Grading Studio에서 출석 확인하기","Grading Studio에서 출석 확인 안 함","{grade}: {n}%부터","성적: {list}",{one:"1개 항목 가져오기",other:"{n}개 항목 가져오기"},"성적은 최대 100%","확인하기",{one:"채점하면서 고를 의견 1개: “{first}”",other:"채점하면서 고를 의견 {n}개 (예: “{first}”)"},"내 설정 복사","프롬프트 복사","{list}의 과목. 같은 과목의 학급은 서로 연결돼요.","내보내는 기준 답안지의 이름 가리기","내보내는 기준 답안지의 이름 가리지 않기",{one:"설정 1개 항목을 가져왔어요.",other:"설정 {n}개 항목을 가져왔어요."},"아직 아무것도 없는 유형이 있으면 다른 유형으로 계산","아직 아무것도 없는 유형은 0으로 계산","아직 읽을 내용이 없어요. 먼저 설정 글을 붙여 넣으세요.","설정이라기엔 너무 길어요. 설정은 길어야 몇 쪽 분량이에요.","이 글에서 설정을 찾지 못했어요. 설정은 { 로 시작해서 } 로 끝나요. 도우미가 중간에 끊었다면 블록 전체를 다시 달라고 하세요.","이 글은 Grading Studio 설정이 아니에요. ‘gradingStudioSetup’ 줄이 없어요. 프롬프트를 써서 도우미에게 설정 블록을 다시 달라고 하세요.",{one:"달력의 날짜 1개: {list}",other:"달력의 날짜 {n}개: {list}"},"잘 되지 않았고, 바뀐 것은 없어요. 다시 시도해 주세요.","휴식 길이 {n}분",{one:"하루 목표: 1분",other:"하루 목표: {n}분"},{one:"하루 목표: 답안지 1장",other:"하루 목표: 답안지 {n}장"},"공강 시간에 채점 제안","공강 시간에 채점 제안 안 함",{one:"1분 동안 아무 작업이 없으면 시간 세기 멈춤",other:"{n}분 동안 아무 작업이 없으면 시간 세기 멈춤"},"집중 세션 길이 {n}분","수업 계획 세션 길이 {n}분","음악의 분위기, 음량, 배경음","세션 중 로파이 음악 재생","세션 중 음악 없음","하루 목표 없음","집중 세션 밖의 수업 계획은 {n}분 동안 꾸준히 작업하면 세기 시작","수업 계획은 집중 세션 중에만 세기","집중 세션 중에는 개수 숨기기","집중 세션 중에도 개수 표시","세션마다 목표 제안","세션 목표 제안 안 함","집중 세션에서는 짧은 답안부터","집중 세션에서도 답안지는 평소 순서대로","세션이나 휴식이 끝나면 부드러운 소리로 알림","세션이 끝나도 알림음 없음","남은 시간을 브라우저 탭 이름에 표시","남은 시간을 브라우저 탭 이름에 표시 안 함","채점과 수업 계획 시간 세기","채점과 수업 계획 시간 세지 않기","{day}에 한 주 돌아보기",{one:"주간 목표: 1분",other:"주간 목표: {n}분"},"한 주 돌아보기 없음",{one:"주간 목표: 답안지 1장",other:"주간 목표: 답안지 {n}장"},"파일 선택…","타자로 친 이름을 자동으로 찾아서 가리기","이름은 직접 가리기","전체 화면에서는 학생 목록과 도구를 숨기고, 포인터를 대면 보이기","전체 화면에서는 학생 목록을 숨기고, 포인터를 대면 보이기","전체 화면에서도 학생 목록과 도구를 답안지 옆에 두기",{one:"목표 1개: {list}",other:"목표 {n}개: {list}"},"내 설정","출석","성적 구성","학기와 쉬는 날","학급과 시간표","저장한 코멘트","수업 슬라이드","집중 타이머와 하루 목표","학습 목표","평가 방식","채점과 돌려주기","사이드 패널 너비","저장한 루브릭","학교","학급 탭","학기","할 일","{list}의 IB 교육 과정, 평가 기준, 등급 경계","검정","파랑","초록","보라","빨강",{one:"글에 학생에 관한 내용이 하나 있어서 빼 두었어요. 학생은 학급 페이지에서만 추가할 수 있어요.",other:"글에 학생에 관한 내용이 {n}개 있어서 빼 두었어요. 학생은 학급 페이지에서만 추가할 수 있어요."},"{list}의 학교 시스템 링크","{list} 외 {n}개","학생 목록에 백분율 표시","학생 목록에 총점 대비 점수 표시","이메일 버튼을 누르면 컴퓨터의 메일 앱 열기","이메일 버튼을 누르면 Gmail에서 새 메일 열기","이메일 버튼을 누르면 웹용 Outlook에서 새 메일 열기",{one:"새 학급: {list}",other:"새 학급 {n}개: {list}"},"‘슬라이드 추가’를 누르면 {name} 슬라이드가 추가돼요","2번 슬라이드에 수업 순서 넣지 않기","성적이 100%를 넘을 수 있음","일부는 더 새 버전용이거나 이 버전이 모르는 방식으로 쓰여 있어서 그대로 두었어요.",{one:"쉬는 날 1일: {list}",other:"쉬는 날 {n}일: {list}"},"입력용 목록은 이름 순서","입력용 목록은 성 순서","입력용 목록은 명단 순서","여기 있는 내용으로 만든 같은 형식의 글이에요. 다른 컴퓨터나 동료에게 쓸 수 있어요. 명단, 점수, 답안지는 절대 들어가지 않아요.","내 설정","설정 글","‘학교’ 페이지의 사람들: {list}","바뀌는 내용","교육 과정: {name}","점수를 득점에 따라 색으로 구분: 만점, 부분 점수, 0점","점수는 {ink}(으)로 써요","점수는 펜 색으로 써요","‘학교’ 페이지의 담당 자리: {list}","루브릭 항목: {list}","재응시하면 모든 시도의 평균을 반영","재응시하면 가장 높은 점수를 반영","재응시하면 가장 최근 점수를 반영",{one:"{name} (1개 항목)",other:"{name} ({n}개 항목)"},{one:"새 루브릭: {list}",other:"새 루브릭 {n}개: {list}"},"이미 있는 {list}의 새 문구","이미 저장된 날은 그대로 남아요.","모든 학급에 적용돼요. 점수는 바뀌지 않고, 성적은 점수로 다시 계산돼요.","달력에 추가돼요. 이미 있는 쉬는 날은 그대로 남아요.","이미 있는 학급은 학생과 과제와 함께 그대로 남아요. 이걸로 학생이 추가되지는 않아요.","채점하면서 고르는 의견에 추가돼요.","앞으로 만드는 모든 슬라이드에 적용돼요.","루브릭 항목과 퀴즈 문항에 붙이는 용도예요.","이미 있는 과제는 자체 루브릭과 척도를 그대로 쓰고, 점수는 바뀌지 않아요.","답안지, 표시, 점수는 바뀌지 않아요.","어느 과제에서든 ‘루브릭 설정’에서 고를 수 있어요.","앱에 표시되는 이름으로만 쓰여요. 이것들과 연결되는 것은 없어요.","다른 페이지는 ‘더 보기’ 아래에 그대로 있어요.","과제는 마감일이 속한 학기에 반영돼요.","삭제됨: {list}. 그 항목들은 단어가 맞는 분류로 옮겨져요.","바뀌는 것이 없어요. 모두 지금 설정과 같아요.","파일로 저장",{one:"점수를 백분율로 바꾸는 성적 척도 (1단계)",other:"점수를 백분율로 바꾸는 성적 척도 ({n}단계)"},"먼저 읽기","어시스턴트에게 줄 프롬프트","학기: {from}~{to}","성적표에 답안지에서 찾은 성적도 표시","성적표에는 앱에서 준 점수만 표시","슬라이드 글자는 28~36pt","슬라이드 글자는 18~44pt 중 아무 크기나","프롬프트를 복사해서 AI 도우미에게 주세요. 아직 모르는 것을 물어본 뒤 설정을 써 줘요.","프롬프트를 복사해서 {name}에게 주세요. 아직 모르는 것을 물어본 뒤 설정을 써 줘요.","돌려받은 내용을 여기에 붙여 넣고 확인하세요. 무엇이 바뀌는지 보기 전까지는 아무것도 바뀌지 않아요.","학생은 {name}에서 과제를 내요","지정된 학교 시스템 없음","형성 평가","수업 중","총괄","출석","차트","학습 목표","성적부","미제출 과제","다른 페이지","성적표 의견","자리 배치","학생","탭 줄에 두기: {list}","탭 줄에는 과제, 성적부, 학생만","할 일 분류: {list}","항목을 {name}(으)로 보내는 단어: {words}","{name}: {from} – {to}","{name}을(를) {from}~{to}로 옮겨요","{list}의 수업 시간 (시간표에 들어가요)","항목마다 0~{n}점으로 채점","항목마다 0~{n}점으로 채점, 정수만","총 {n}점 만점으로 채점","직접 만든 유형: {list}","이전 설정으로 되돌리기","설정을 가져오기 전 상태로 되돌렸어요.","되돌렸어요. 다만 그 뒤에 사용한 것은 남겨 두었어요.","단원 계획은 {name}에 보관해요","단원 계획 보관 장소 지정 안 됨","{list}의 새 단원","알아보지 못해서 그대로 두었어요: {list}.","새 과제는 {way}(으)로 시작해요","IB 1~7","등급(A~F)","IB MYP 평가 기준","백분율","점","루브릭 항목","새 과제는 {way}(으)로 시작해요 (지금은 {was})","학기 성적은 {list}","추가 점수는 수업 중 과제에 더해져요","추가 점수는 학기 성적에 더해져요","돌려주는 파일에 학생과 과제 이름 붙이기","돌려주는 파일은 제출할 때 이름 그대로","학생마다 모든 답안지를 담은 PDF 하나","답안지마다 각각 파일로 돌려주기","다시 로그인","매시간 자동으로 갱신","Google은 한 시간마다 다시 확인해요. 켜 두면 보통 앱으로 돌아올 때 Google의 작은 창이 잠깐 열려요. 끄면 ‘다시 로그인’을 누를 때까지 동기화를 기다려요.","로그인 창이 닫혔어요.","로그인이 끝나지 않았어요.","Google로 로그인하면 학급, 점수, 수업 계획, 할 일이 로그인한 모든 컴퓨터와 휴대폰에서 똑같이 유지돼요. Drive 안에 있는 앱 전용 숨김 폴더만 쓰고, Drive의 다른 내용은 볼 수 없어요.","Google 드라이브","마지막 동기화: {when}","Google 로그인은 앱의 웹 주소에서만 돼요. 파일로 연 사본에서는 안 돼요.","Google에 연결하지 못했어요. 인터넷 연결을 확인해 주세요.","Google에서 로그아웃했어요","샘플을 열어 둔 동안에는 Google Drive를 쓰지 않아요.","Google로 로그인","로그아웃","Google: {email}","{email}(으)로 로그인했어요","페이지가 앞에 올 때까지 기다리는 중","표시는 동기화됨. Google Drive가 가득 차서 답안지는 여기에 남아요","동기화 안 됨","표시는 동기화됨. 답안지는 아직 보내지 않았어요","오프라인: 다시 연결되면 동기화해요","저장 중…","답안지 보내는 중…","동기화하려면 다시 로그인","동기화됨","동기화 중…","지금 동기화","화면에 표시되는 말에만 쓰입니다. 아무것도 연결되지 않습니다.","학생이 과제를 제출하는 곳","이름","우리 학교 시스템","종이로, 또는 지정 안 함","다른 곳…","학생이 과제를 내는 곳 바꾸기","터치 화면용입니다. 마우스와 트랙패드는 지금까지처럼 작동합니다.","펜을 쓰기 전까지는 그리고, 그 뒤로는 페이지를 움직임","항상 그림","제출물 위의 손가락","태블릿과 펜","항상 페이지를 움직임","펜을 세게 누를수록 선이 굵어짐","두 손가락은 항상 페이지를 움직이고, 오므리고 벌리면 확대됩니다. 펜이 제출물 위에 있는 동안에는 화면에 올려 둔 손이 반응하지 않습니다.","AI에게 설정 맡기기","선생님의 수업 방식을 아는 AI 도우미가 있나요?","학급 더 추가","다른 학급","뒤로","작업 가져오기","Grading Studio 폴더를 고르거나, 가져가기 파일을 불러오세요. 학급과 작업도 함께 들어와요.","답을 저장하지 못했어요. 다시 시도해 주세요.","학급 이름(예: 2학년 3반 생물)","계속","준비됐어요. 여기서 답안지를 열거나, 사이드바에서 학급을 추가하세요.","준비됐어요. 여기서 학급의 답안지를 열거나, 사이드바에서 학급을 클릭해 학생을 추가하세요.","폴더 선택…","이 브라우저와 함께 ‘{name}’ 폴더에도 저장하고 있어요.","보통 어떻게 평가하나요?","새 과제의 기본값일 뿐입니다. 과제마다 다른 방식으로 채점할 수 있습니다.","답안지 채점, 수업 계획, 과제 돌려주기.","학생들은 어디에 제출하나요?","이름","학교 시스템의 이름","학급, 제출물, 표시, 점수는 이 브라우저에 저장됩니다. 이 브라우저는 스스로 폴더에 저장할 수 없으므로(컴퓨터의 Chrome 또는 Edge는 가능) 가끔 설정에서 휴대용 파일을 만드세요. 사이드바에서 알려 드립니다.","작업을 어디에 저장할까요?","학급, 제출물, 표시, 점수는 이 브라우저에 저장됩니다. 이 컴퓨터의 폴더를 선택하면 저장할 때마다 그곳에도 저장되고, 날짜별 사본으로 되돌아갈 수 있습니다. 아무것도 업로드되지 않습니다.","나중에 ‘설정’에서 해도 돼요.","간단한 질문 세 가지에 답하면 채점을 시작할 수 있습니다. 답은 나중에 모두 바꿀 수 있습니다.","학생 이름은 선택 사항이며 나중에 추가할 수 있습니다. 학급 페이지에 명단을 붙여넣거나 건너뛰세요.","다른 컴퓨터에서 이미 Grading Studio를 사용하나요?","종이, 또는 답하지 않음","학급","평가 방식","저장 위치","먼저 샘플 학급으로 둘러보기","시작","3단계 중 {n}단계","앱에서 그 이름을 표시하기 위한 것입니다. 연결되지 않으며 아무것도 전송되지 않습니다.","어떤 학급을 가르치나요?","그대로 채점하거나, 어디서나 표시할 수 있는 PDF 페이지로 바꿉니다. Word 파일은 항상 보관됩니다.","Word 제출물","Word로 유지","PDF 페이지로 변환"],null);export{i as default};
